const cfg = $('Configuração').first().json;
const b = cfg.form || {};
// Números: aceita vírgula ou ponto. Vazio = null. Texto inválido = valor impossível, que a função na BD recusa com mensagem clara.
const num = (v, invalido) => { const s = String(v == null ? '' : v).trim().replace(/\s/g, '').replace(',', '.'); if (s === '') return null; const x = Number(s); return Number.isFinite(x) ? x : invalido; };
const uuid = (v) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(v || '').trim()) ? String(v).trim().toLowerCase() : null;
const txt = (v, n) => { const s = String(v == null ? '' : v).trim().slice(0, n); return s === '' ? null : s; };
const dias = num(b.validade_dias, 0);
return [{ json: { rpc: {
  p_token: cfg.token,
  p_preco_kg: num(b.preco_kg, null),
  p_desconto_pct: num(b.desconto_pct, -1),
  p_cotacao_id: uuid(b.cotacao_id),
  p_valor_frete: num(b.valor_frete, -1),
  p_iva_regime: txt(b.iva_regime, 30),
  p_iva_pct: num(b.iva_pct, -1),
  p_cliente_nif: txt(b.cliente_nif, 20),
  p_validade_dias: dias === null ? null : Math.round(dias),
  p_notas: txt(b.notas, 1000)
} } }];

const cfg = $('Configuração').first().json;
const r = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = (n, d = 2) => { const x = Number(n); if (n === null || n === undefined || n === '' || !isFinite(x)) return '-'; const p = Math.abs(x).toFixed(d).split('.'); return (x < 0 ? '-' : '') + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + (d ? ',' + p[1] : ''); };
const dataPt = (v) => /^\d{4}-\d{2}-\d{2}/.test(String(v || '')) ? String(v).slice(8, 10) + '/' + String(v).slice(5, 7) + '/' + String(v).slice(0, 4) : '-';
const httpDe = (e) => /expirou/.test(e) ? 410 : /permissão/.test(e) ? 403 : /não é válida/.test(e) ? 404 : /estado/.test(e) ? 409 : 400;
const CSS = 'body{font-family:Arial,Helvetica,sans-serif;background:#f7efe2;color:#2a1c11;max-width:640px;margin:24px auto;padding:0 16px;line-height:1.45}h1{font-size:24px}table{border-collapse:collapse;width:100%;background:#fff;border:2px solid #3e5b3a;border-radius:10px}td{padding:6px 12px;border-bottom:1px solid #e3d5bf}td.v{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.total td{font-size:20px;font-weight:bold}.aviso{background:#fff3cd;border-left:4px solid #c9a227;padding:8px 12px;margin:10px 0}.erro{background:#fde8e5;border-left:4px solid #a3261b;padding:8px 12px}.ok{background:#e6f1e4;border-left:4px solid #3e5b3a;padding:8px 12px}a{color:#3e5b3a;font-weight:bold}';
const moldura = (titulo, corpo) => '<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>' + esc(titulo) + '</title><style>' + CSS + '</style></head><body>' + corpo + '</body></html>';
const voltar = cfg.url_pagina + '?t=' + encodeURIComponent(cfg.token);
if (!r.ok) {
  const erro = String(r.erro || 'Não foi possível gravar o preço.');
  return [{ json: { gravado: false, http: httpDe(erro), html: moldura('Preço não gravado', '<h1>O preço não foi gravado</h1><p class="erro">' + esc(erro) + '</p><p><a href="' + esc(voltar) + '">Voltar à página do preço</a></p>') } }];
}
const REG = { pt_normal: 'IVA 23 %', ue_isento: 'Isento, UE (art. 14.º RITI)', exportacao_isento: 'Isento, exportação (art. 14.º CIVA)', outro: 'IVA ' + fmt(r.iva_pct) + ' %' };
const linha = (k, v, cls) => '<tr' + (cls ? ' class="' + cls + '"' : '') + '><td>' + esc(k) + '</td><td class="v">' + v + '</td></tr>';
const avisos = Array.isArray(r.avisos) ? r.avisos : [];
const corpo = '<h1>Preço gravado · ' + esc(r.codigo) + '</h1><p class="ok">' + (r.preco_alterado ? 'O preço foi alterado (antes: ' + fmt(r.preco_anterior) + ' €).' : 'O preço ficou definido.') + '</p>'
  + avisos.map(a => '<p class="aviso">' + esc(a) + '</p>').join('')
  + '<table>' + linha('Produto: ' + fmt(r.quantidade_kg, 0) + ' kg × ' + fmt(r.preco_kg, 4) + ' €/kg' + (Number(r.desconto_pct) ? ' − ' + fmt(r.desconto_pct) + ' %' : ''), fmt(r.valor_produto) + ' €')
  + linha('Frete' + (r.frete_corrigido ? ' (valor corrigido à mão)' : ''), fmt(r.valor_frete) + ' €') + linha('Valor líquido', fmt(r.valor_liquido) + ' €')
  + linha(REG[r.iva_regime] || 'IVA', fmt(r.valor_iva) + ' €') + linha('Total da proposta', fmt(r.preco_final) + ' €', 'total') + '</table>'
  + '<p>Validade da proposta: até <b>' + dataPt(r.validade_proposta) + '</b>.</p><p>Vai receber por email o resumo atualizado, com um <b>código de aprovação novo</b>. Para aprovar, responda a esse email com OK e o código. Os códigos anteriores deixam de valer.</p><p><a href="' + esc(voltar) + '">Alterar outra vez</a></p>';
const slack = '💶 Preço da *' + r.codigo + '* ' + (r.preco_alterado ? 'alterado' : 'definido') + ' por ' + r.utilizador + ': total ' + fmt(r.preco_final) + ' € (líquido ' + fmt(r.valor_liquido) + ' €, ' + (REG[r.iva_regime] || 'IVA') + ')' + (r.preco_alterado ? ' · antes ' + fmt(r.preco_anterior) + ' €' : '') + (avisos.length ? ' · ⚠️ ' + avisos.length + ' aviso(s)' : '');
return [{ json: { gravado: true, http: 200, codigo: r.codigo, slack_texto: slack, html: moldura('Preço gravado ' + r.codigo, corpo) } }];

const cfg = $('Configuração').first().json;
const r = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = (n, d = 2) => { const x = Number(n); if (n === null || n === undefined || n === '' || !isFinite(x)) return '-'; const p = Math.abs(x).toFixed(d).split('.'); return (x < 0 ? '-' : '') + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + (d ? ',' + p[1] : ''); };
const dataPt = (v) => /^\d{4}-\d{2}-\d{2}/.test(String(v || '')) ? String(v).slice(8, 10) + '/' + String(v).slice(5, 7) + '/' + String(v).slice(0, 4) : '-';
const httpDe = (e) => /expirou/.test(e) ? 410 : /permissão/.test(e) ? 403 : /não é válida/.test(e) ? 404 : /estado/.test(e) ? 409 : 400;
const CSS = 'body{font-family:Arial,Helvetica,sans-serif;background:#f7efe2;color:#2a1c11;max-width:760px;margin:24px auto;padding:0 16px;line-height:1.45}h1{font-size:24px;margin:0 0 4px}h2{font-size:18px;margin:22px 0 8px;border-bottom:2px solid #d9b98f;padding-bottom:4px}.ref{color:#6b5237;font-size:14px}table{border-collapse:collapse;width:100%}td{padding:5px 8px;border-bottom:1px solid #e3d5bf;vertical-align:top}td.v{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}label{display:block;font-weight:bold;margin:12px 0 4px}input[type=number],input[type=text],select,textarea{font-size:16px;padding:7px 9px;border:1px solid #b89b78;border-radius:6px;background:#fff;color:#2a1c11;width:100%;box-sizing:border-box}.cot{display:flex;gap:10px;align-items:flex-start;padding:10px;border:1px solid #d9c3a3;border-radius:8px;margin:6px 0;background:#fffaf2;font-weight:normal}.cot input{margin-top:4px}.ajuda{font-size:13px;color:#6b5237;margin-top:3px}.rever{color:#a3261b;font-weight:bold}.aviso{background:#fff3cd;border-left:4px solid #c9a227;padding:8px 12px;margin:10px 0}.erro{background:#fde8e5;border-left:4px solid #a3261b;padding:8px 12px}.ok{background:#e6f1e4;border-left:4px solid #3e5b3a;padding:8px 12px}.resumo{background:#fff;border:2px solid #3e5b3a;border-radius:10px;padding:12px 16px;margin-top:18px}.total td{font-size:20px;font-weight:bold;border-bottom:0}button{margin-top:18px;background:#3e5b3a;color:#fff;border:0;border-radius:8px;padding:12px 22px;font-size:17px;font-weight:bold;cursor:pointer}a{color:#3e5b3a}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}@media(max-width:560px){.grid2{grid-template-columns:1fr}}';
const moldura = (titulo, corpo, script) => '<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>' + esc(titulo) + '</title><style>' + CSS + '</style></head><body>' + corpo + (script ? '<script>' + script + '</script>' : '') + '</body></html>';
if (!r.ok) {
  const erro = String(r.erro || 'Não foi possível abrir a página do preço.');
  return [{ json: { http: httpDe(erro), html: moldura('Preço da proposta', '<h1>Não é possível definir o preço</h1><p class="erro">' + esc(erro) + '</p><p>Se precisar de ajuda, contacte o responsável técnico.</p>') } }];
}
const P = r.proposta || {};
const lim = r.limites || {};
const cots = Array.isArray(r.cotacoes) ? r.cotacoes : [];
const fo = !!r.frete_obrigatorio;
const sug = r.iva_sugerido;
const REG = { pt_normal: 'Portugal: IVA 23 %', ue_isento: 'UE, cliente com NIF: isento (art. 14.º RITI)', exportacao_isento: 'Fora da UE: isento, exportação (art. 14.º CIVA)', outro: 'Outro regime (indicar a taxa)' };
const POR = { total: 'total', camiao: 'por camião', palete: 'por palete', nao_claro: 'âmbito não claro' };
const unid = (v, u) => { const s = String(v == null ? '' : v).trim(); if (!s) return '-'; return /[a-z]/i.test(s) ? s : s + ' ' + u; };
const linha = (k, v) => '<tr><td>' + esc(k) + '</td><td>' + esc(v) + '</td></tr>';
let html = '<h1>Definir o preço · ' + esc(P.codigo) + '</h1><div class="ref">' + esc(r.utilizador) + ' · ligação pessoal, não a reencaminhe</div>';
if (P.preco_final != null) html += '<p class="aviso">Esta proposta já tem um preço: <b>' + fmt(P.preco_final) + ' €</b>. Se gravar, o preço é substituído e recebe um resumo novo, com um código de aprovação novo.</p>';
html += '<h2>Pedido</h2><table>' + linha('Cliente', P.cliente) + linha('Produto', P.produto + ' · ' + unid(P.densidade, 'kg/m³') + ' · ' + unid(P.granulometria, 'mm')) + linha('Quantidade', fmt(P.quantidade_kg, 0) + ' kg' + (P.unidade === 't' ? ' (' + fmt(P.quantidade, 2) + ' t)' : '')) + linha('Embalagem', P.embalagem) + linha('Incoterm e destino', P.incoterm + ' · ' + P.destino_pais + (P.destino_local ? ' (' + P.destino_local + ')' : '')) + '</table>';
html += '<form method="post" action="' + esc(cfg.url_pagina) + '" id="f"><input type="hidden" name="t" value="' + esc(cfg.token) + '">';
html += '<h2>Produto</h2><div class="grid2"><div><label for="preco_kg">Preço (€/kg)</label><input type="number" id="preco_kg" name="preco_kg" step="0.0001" min="0.0001" max="' + esc(lim['preco.max_eur_kg'] || 50) + '" required value="' + esc(P.preco_kg != null ? P.preco_kg : '') + '"></div><div><label for="desconto_pct">Desconto (%)</label><input type="number" id="desconto_pct" name="desconto_pct" step="0.01" min="0" max="' + esc(lim['preco.max_desconto_pct'] || 50) + '" value="' + esc(P.desconto_pct != null ? P.desconto_pct : 0) + '"></div></div>';
html += '<h2>Frete</h2>';
if (!fo) {
  html += '<p>Com o Incoterm <b>' + esc(P.incoterm) + '</b> o frete não entra no preço.</p>';
} else if (!cots.length) {
  html += '<p class="erro">Com o Incoterm <b>' + esc(P.incoterm) + '</b> o frete entra no preço, mas ainda não há cotações de frete registadas. Volte quando chegar a primeira cotação.</p>';
} else {
  html += '<p>Com o Incoterm <b>' + esc(P.incoterm) + '</b> o frete entra no preço. Escolha a cotação:</p>';
  cots.forEach((c, i) => {
    const marcada = P.cotacao_id ? c.id === P.cotacao_id : cots.length === 1;
    html += '<label class="cot"><input type="radio" name="cotacao_id" value="' + esc(c.id) + '" data-frete="' + esc(c.frete_proposto != null ? c.frete_proposto : '') + '"' + (marcada ? ' checked' : '') + ' required><span><b>' + esc(c.transportadora) + '</b>' + (c.ref ? ' · ref. ' + esc(c.ref) : '') + ' · ' + esc(c.modo || '-') + '<br>' + (c.preco != null ? fmt(c.preco) + ' ' + esc(c.moeda || 'EUR') : 'sem preço') + ' (' + esc(POR[c.preco_por] || 'âmbito não indicado') + ') · trânsito ' + (c.transito_dias != null ? esc(c.transito_dias) + ' dias' : '-') + ' · válida até ' + dataPt(c.validade) + '<br>' + (c.frete_proposto != null ? 'Frete proposto: <b>' + fmt(c.frete_proposto) + ' €</b>' : '<span class="rever">Frete por calcular: escreva o valor abaixo</span>') + (c.revisao === 'a_rever' ? ' · <span class="rever">cotação a rever</span>' : '') + '</span></label>';
  });
  html += '<label for="valor_frete">Valor do frete (€), opcional</label><input type="number" id="valor_frete" name="valor_frete" step="0.01" min="0" value="' + esc(P.cotacao_id && P.valor_frete != null ? P.valor_frete : '') + '"><div class="ajuda">Deixe vazio para usar o frete proposto da cotação escolhida. Se escrever um valor, fica registado como corrigido.</div>';
}
html += '<h2>IVA</h2><label for="iva_regime">Regime</label><select id="iva_regime" name="iva_regime">' + Object.keys(REG).map(k => '<option value="' + k + '"' + ((P.iva_regime || sug) === k ? ' selected' : '') + '>' + esc(REG[k]) + (k === sug ? ' (sugerido)' : '') + '</option>').join('') + '</select><div class="ajuda">Sugerido pelo país de destino. Se escolher outro, explique porquê nas notas.</div>';
html += '<div class="grid2"><div><label for="cliente_nif">NIF do cliente (com o código do país)</label><input type="text" id="cliente_nif" name="cliente_nif" maxlength="20" placeholder="ex.: NL123456789B01" value="' + esc(P.cliente_nif || '') + '"><div class="ajuda">Obrigatório para a isenção na UE.</div></div><div><label for="iva_pct">Taxa de IVA (%) se «Outro regime»</label><input type="number" id="iva_pct" name="iva_pct" step="0.01" min="0" max="30" value="' + esc(P.iva_regime === 'outro' && P.iva_pct != null ? P.iva_pct : '') + '"></div></div>';
html += '<h2>Condições</h2><label for="validade_dias">Validade da proposta (dias)</label><input type="number" id="validade_dias" name="validade_dias" step="1" min="1" max="90" value="' + esc(lim['preco.validade_dias'] || 30) + '"><label for="notas">Notas (opcional; obrigatórias se mudar o regime de IVA)</label><textarea id="notas" name="notas" maxlength="1000" rows="3">' + esc(P.preco_notas || '') + '</textarea>';
html += '<div class="resumo" id="resumo" aria-live="polite"></div><button type="submit"' + (fo && !cots.length ? ' disabled' : '') + '>Gravar preço</button><div class="ajuda">O sistema volta a calcular e a validar tudo ao gravar. Nada é enviado ao cliente: depois de gravar recebe o resumo atualizado para aprovar.</div></form>';
const dados = JSON.stringify({ kg: Number(P.quantidade_kg) || 0, fo: fo }).replace(/</g, '\\u003c');
const script = 'var D=' + dados + ';var F=document.getElementById("f");function n(v){v=String(v||"").trim().replace(/\\s/g,"").replace(",",".");return v===""?null:Number(v)}function f(x){if(!isFinite(x))return "-";var p=Math.abs(x).toFixed(2).split(".");return (x<0?"-":"")+p[0].replace(/\\B(?=(\\d{3})+(?!\\d))/g," ")+","+p[1]+" €"}function c(){var p=n(F.preco_kg.value)||0,d=n(F.desconto_pct.value)||0;var prod=Math.round(D.kg*p*(1-d/100)*100)/100;var fr=0;if(D.fo){var s=F.querySelector("input[name=cotacao_id]:checked");var m=F.valor_frete?n(F.valor_frete.value):null;fr=m!==null?m:(s&&s.getAttribute("data-frete")!==""?Number(s.getAttribute("data-frete")):NaN)}var r=F.iva_regime.value;var t=r==="pt_normal"?23:(r==="outro"?(n(F.iva_pct.value)||0):0);var l=Math.round((prod+fr)*100)/100;var i=Math.round(l*t)/100;document.getElementById("resumo").innerHTML="<table><tr><td>Produto</td><td class=v>"+f(prod)+"</td></tr>"+(D.fo?"<tr><td>Frete</td><td class=v>"+(isFinite(fr)?f(fr):"por indicar")+"</td></tr>":"")+"<tr><td>Valor líquido</td><td class=v>"+f(l)+"</td></tr><tr><td>IVA ("+t+" %)</td><td class=v>"+f(i)+"</td></tr><tr class=total><td>Total da proposta</td><td class=v>"+f(l+i)+"</td></tr></table>"}F.addEventListener("input",c);F.addEventListener("change",c);c();';
return [{ json: { http: 200, html: moldura('Preço da proposta ' + (P.codigo || ''), html, script) } }];
